export function classworkState(a,staff,today){if(a.status==='draft')return'draft';if(staff)return a.submittedCount>a.returnedCount?'marking':'published';const s=a.submission;if(s?.returnedAt)return'returned';if(s?.turnedInAt)return'submitted';if(a.due&&a.due<today)return'overdue';return s?'working':'assigned';}
export function classworkList(assignments,{staff=false,today=new Date(Date.now()+5*3600000).toISOString().slice(0,10),topic='',search='',status='',offset=0}={}){const query=String(search).trim().toLocaleLowerCase(),all=assignments.filter(a=>(!topic||a.topic===topic)&&(!query||[a.title,a.description,a.topic].join(' ').toLocaleLowerCase().includes(query))&&(!status||classworkState(a,staff,today)===status)).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')||a.title.localeCompare(b.title)),limit=10,n=Number(offset),start=all.length?Math.min(Number.isSafeInteger(n)&&n>=0?Math.floor(n/limit)*limit:0,Math.floor((all.length-1)/limit)*limit):0;return{rows:all.slice(start,start+limit),total:all.length,offset:start,limit,topics:[...new Set(assignments.map(a=>a.topic))].sort()};}
export function createClassworkListUI({e,link}){function page(assignments,staff,p){const data=classworkList(assignments,{staff,topic:p.get('workTopic')||'',search:p.get('workSearch')||'',status:p.get('workStatus')||'',offset:p.get('workOffset')||0}),base={class:p.get('class'),tab:'classwork',...(p.get('unit')?{unit:p.get('unit')}:{})},filters={...base,...Object.fromEntries(['workTopic','workSearch','workStatus'].filter(k=>p.get(k)).map(k=>[k,p.get(k)]))},options=staff?[['draft','Drafts'],['marking','Awaiting marking'],['published','Published · no marking pending']]:[['assigned','To do'],['working','Saved drafts'],['overdue','Overdue'],['submitted','Handed in'],['returned','Returned']],labels={draft:'Draft',marking:'Awaiting marking',published:'Published',assigned:'To do',working:'Saved draft',overdue:'Overdue',submitted:'Handed in',returned:'Returned'};return '<form data-classwork-filters class="community-filters">'+Object.entries(base).map(([k,v])=>'<input type="hidden" name="'+k+'" value="'+e(v)+'">').join('')+'<label>Topic<select name="workTopic" aria-label="Classwork topic"><option value="">All topics</option>'+data.topics.map(t=>'<option '+(t===p.get('workTopic')?'selected':'')+' value="'+e(t)+'">'+e(t)+'</option>').join('')+'</select></label><label>Show<select name="workStatus" aria-label="Classwork status"><option value="">All work</option>'+options.map(([k,t])=>'<option value="'+k+'" '+(k===p.get('workStatus')?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Find<input name="workSearch" aria-label="Find classwork" maxlength="120" value="'+e(p.get('workSearch')||'')+'" placeholder="Title, topic or instructions"></label><button class="btn">Find work</button>'+link('Clear filters',base)+'</form><p>'+data.total+' matching '+(data.total===1?'task':'tasks')+'</p>'+data.rows.map(a=>'<article class="vle-assignment"><span class="vle-task-icon">▤</span><div><h3>'+link(a.title,{class:base.class,assignment:a.id})+'</h3><small>'+e(a.topic)+' · '+(a.kind==='quiz'?'Quiz · ':'')+(a.due?'Due '+e(a.due):'No due date')+' · '+a.maximum+' points</small></div><span class="vle-status">'+labels[classworkState(a,staff,new Date(Date.now()+5*3600000).toISOString().slice(0,10))]+(staff?' · '+a.submittedCount+' handed in':'')+'</span></article>').join('')+(!data.total?'<p class="learning-empty">No classwork matches these filters.</p>':'')+'<div class="vle-actions">'+(data.offset?link('← Previous',{...filters,workOffset:Math.max(0,data.offset-data.limit)}):'')+(data.offset+data.limit<data.total?link('Next →',{...filters,workOffset:data.offset+data.limit}):'')+'</div>';}
 function bind(root){root.querySelector('[data-classwork-filters]')?.addEventListener('submit',ev=>{ev.preventDefault();location.hash='/classroom?'+new URLSearchParams([...new FormData(ev.currentTarget)].filter(([,v])=>v));});}return{page,bind};}
